INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_CHR_HERESY','Christian Heresy and Dissent',300,1400)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_PELIKAN_CT','secondary scholarship','Jaroslav Pelikan, The Christian Tradition: A History of the Development of Doctrine (Univ. of Chicago Press, 1971-1989)','Doctrinal history of ancient heresiarchs (Arius, Nestorius, Pelagius, Eutyches, Sabellius, etc.) and conciliar definitions'),
 ('SRC_LAMBERT_MH','secondary scholarship','Malcolm Lambert, Medieval Heresy: Popular Movements from the Gregorian Reform to the Reformation (3rd ed., Blackwell, 2002)','Medieval dualist and dissenting movements: Bogomils, Cathars, Paulicians, Waldensians, Bosnian Church')
INSERT INTO _e VALUES
 ('ENT_HERX_HERESIARCHS','Christian Heresiarchs and Dissenting Movements','collective','collective','Christian/Heterodox','heresy; dissent; dualism','B','Hub collective for intra-Christian heterodox figures and movements condemned by the ecumenical councils; modern category attested throughout Pelikan and Lambert.'),
 ('ENT_HERX_ARIUS','Arius','figure','heresiarch','Christian/Heterodox','Christology; subordinationism','B','Alexandrian presbyter (c.256-336) whose teaching that the Son was created and subordinate to the Father was condemned at Nicaea (325); attested in Athanasius, Socrates Scholasticus, and Pelikan.'),
 ('ENT_HERX_NESTORIUS','Nestorius','figure','heresiarch','Christian/Heterodox','Christology; dyophysitism','B','Patriarch of Constantinople (c.386-450) condemned at Ephesus (431) for teaching two distinct persons in Christ and rejecting Theotokos; attested in Pelikan.'),
 ('ENT_HERX_PELAGIUS','Pelagius','figure','heresiarch','Christian/Heterodox','grace; free will; soteriology','B','British ascetic (c.354-418) who denied original sin''s bondage of the will, condemned at Carthage (418) and Ephesus (431); chief antagonist of Augustine, attested in Pelikan.'),
 ('ENT_HERX_DONATUS','Donatus Magnus','figure','heresiarch','Christian/Heterodox','ecclesiology; sacramental purity','B','Bishop of Carthage (d. c.355) and eponym of the Donatist schism over the validity of sacraments administered by traditores; attested in Pelikan.'),
 ('ENT_HERX_MONTANUS','Montanus','figure','heresiarch','Christian/Heterodox','prophecy; New Prophecy; eschatology','B','2nd-c. Phrygian founder of the New Prophecy (Montanism), an ecstatic prophetic movement condemned for novel revelation; attested in Eusebius and Pelikan.'),
 ('ENT_HERX_PRISCILLIAN','Priscillian','figure','heresiarch','Christian/Heterodox','asceticism; dualism','C','Bishop of Avila (d. 385), ascetic teacher executed for heresy/sorcery, first Christian put to death by the state for heterodoxy; attested in Sulpicius Severus and Pelikan.'),
 ('ENT_HERX_EUTYCHES','Eutyches','figure','heresiarch','Christian/Heterodox','Christology; monophysitism','B','Constantinopolitan archimandrite (c.380-456) whose teaching of a single divine nature in Christ was condemned at Chalcedon (451); attested in Pelikan.'),
 ('ENT_HERX_SABELLIUS','Sabellius','figure','heresiarch','Christian/Heterodox','Trinity; modalism','C','Early 3rd-c. teacher of modalist monarchianism (the Father, Son, and Spirit as modes of one person), eponym of Sabellianism; attested in Hippolytus and Pelikan.'),
 ('ENT_HERX_BOGOMILS','The Bogomils','collective','movement','Christian/Heterodox','dualism; anticlericalism','B','10th-c. Balkan dualist movement founded under the priest Bogomil rejecting the material order and ecclesiastical hierarchy; transmitter of dualism westward, attested in Lambert.'),
 ('ENT_HERX_CATHAR_PERFECTI','The Cathar Perfecti (Albigensians)','collective','movement','Christian/Heterodox','dualism; asceticism','B','The consoled elect of the Cathar/Albigensian dualist church of Languedoc and Lombardy (12th-13th c.), suppressed in the Albigensian Crusade; attested in Lambert.'),
 ('ENT_HERX_PAULICIANS','The Paulicians','collective','movement','Christian/Heterodox','dualism; iconoclasm','C','7th-9th c. Armenian/Byzantine dualist sect rejecting the material world, the Old Testament, and church sacraments; precursor in the dualist transmission to the Bogomils, attested in Lambert.'),
 ('ENT_HERX_WALDO','Peter Waldo','figure','heresiarch','Christian/Heterodox','apostolic poverty; lay preaching','B','Lyon merchant (c.1140-c.1205) who founded the Waldensian movement of apostolic poverty and unauthorized lay preaching, condemned 1184; attested in Lambert.'),
 ('ENT_HERX_WALDENSES','The Waldensians','collective','movement','Christian/Heterodox','apostolic poverty; biblicism; dissent','B','The Poor of Lyon, an evangelical dissenting movement of vernacular preaching and biblicism founded by Peter Waldo, surviving into the Reformation; attested in Lambert.'),
 ('ENT_HERX_BOSNIAN_CHURCH','The Bosnian Church','collective','movement','Christian/Heterodox','schism; dissent','C','Medieval autonomous Bosnian church (13th-15th c.) long associated with dualist/Bogomil influence and condemned as heretical by both Rome and Constantinople; attested in Lambert.');
