INSERT INTO _r VALUES
 ('ENT_HERX_ARIUS','member_of','ENT_HERX_HERESIARCHS','high','Arius is a foundational ancient heresiarch in the heterodox collective.'),
 ('ENT_HERX_NESTORIUS','member_of','ENT_HERX_HERESIARCHS','high','Nestorius is an ancient heresiarch in the heterodox collective.'),
 ('ENT_HERX_PELAGIUS','member_of','ENT_HERX_HERESIARCHS','high','Pelagius is an ancient heresiarch in the heterodox collective.'),
 ('ENT_HERX_DONATUS','member_of','ENT_HERX_HERESIARCHS','high','Donatus is an ancient schismatic/heresiarch in the heterodox collective.'),
 ('ENT_HERX_MONTANUS','member_of','ENT_HERX_HERESIARCHS','high','Montanus is an ancient heresiarch in the heterodox collective.'),
 ('ENT_HERX_PRISCILLIAN','member_of','ENT_HERX_HERESIARCHS','high','Priscillian is an ancient heresiarch in the heterodox collective.'),
 ('ENT_HERX_EUTYCHES','member_of','ENT_HERX_HERESIARCHS','high','Eutyches is an ancient heresiarch in the heterodox collective.'),
 ('ENT_HERX_SABELLIUS','member_of','ENT_HERX_HERESIARCHS','high','Sabellius is an ancient heresiarch in the heterodox collective.'),
 ('ENT_HERX_BOGOMILS','member_of','ENT_HERX_HERESIARCHS','high','The Bogomils are a medieval dualist movement in the heterodox collective.'),
 ('ENT_HERX_CATHAR_PERFECTI','member_of','ENT_HERX_HERESIARCHS','high','The Cathar Perfecti are a medieval dualist movement in the heterodox collective.'),
 ('ENT_HERX_PAULICIANS','member_of','ENT_HERX_HERESIARCHS','high','The Paulicians are a medieval dualist movement in the heterodox collective.'),
 ('ENT_HERX_WALDO','member_of','ENT_HERX_HERESIARCHS','high','Peter Waldo is a medieval heresiarch/founder in the heterodox collective.'),
 ('ENT_HERX_WALDENSES','member_of','ENT_HERX_HERESIARCHS','high','The Waldensians are a medieval dissenting movement in the heterodox collective.'),
 ('ENT_HERX_BOSNIAN_CHURCH','member_of','ENT_HERX_HERESIARCHS','high','The Bosnian Church is a medieval dissenting body in the heterodox collective.'),
 ('ENT_HERX_ARIUS','opposed_by','ENT_ORTH_ATHANASIUS','high','Athanasius of Alexandria was the chief patristic opponent of Arius and Arianism after Nicaea.'),
 ('ENT_ORTH_ATHANASIUS','opposes','ENT_HERX_ARIUS','high','Athanasius led the orthodox defense against Arius''s subordinationist Christology.'),
 ('ENT_HERX_WALDENSES','reception_of','ENT_HERX_WALDO','high','The Waldensian movement received its origin and rule of apostolic poverty from Peter Waldo, its founder.'),
 ('ENT_HERX_BOGOMILS','reception_of','ENT_HERX_PAULICIANS','medium','The Bogomils received and transmitted the dualist cosmology earlier carried by the Paulicians of the Byzantine East (Lambert).'),
 ('ENT_HERX_CATHAR_PERFECTI','reception_of','ENT_HERX_BOGOMILS','high','Western Catharism received its dualist doctrine and ritual (the consolamentum) from Balkan Bogomilism (Lambert).'),
 ('ENT_HERX_BOSNIAN_CHURCH','reception_of','ENT_HERX_BOGOMILS','low','The Bosnian Church was widely (if contestedly) linked to Bogomil dualist influence by medieval polemicists (Lambert).'),
 ('ENT_HERX_PAULICIANS','aligned_with','ENT_MANICH_MANI','medium','Paulician radical dualism was assimilated by Byzantine heresiologists to Manichaean dualism, of which Mani is the founder.'),
 ('ENT_HERX_CATHAR_PERFECTI','aligned_with','ENT_MANICH_MANI','medium','Medieval polemicists labelled the dualist Cathars ''Manichaeans''; their cosmology parallels Manichaean dualism.'),
 ('ENT_HERX_CATHAR_PERFECTI','opposed_by','ENT_SAINT_BERNARD','high','Bernard of Clairvaux preached against the Cathar heretics of the Languedoc in 1145 (Lambert).'),
 ('ENT_SAINT_BERNARD','opposes','ENT_HERX_CATHAR_PERFECTI','high','Bernard of Clairvaux led an early preaching campaign against Catharism.'),
 ('ENT_HERX_CATHAR_PERFECTI','opposed_by','ENT_SAINT_DOMINIC','high','Dominic''s preaching mission and the founding of the Order of Preachers were directed against the Albigensian Cathars (Lambert).'),
 ('ENT_SAINT_DOMINIC','opposes','ENT_HERX_CATHAR_PERFECTI','high','Dominic founded his order to combat the Albigensian heresy.'),
 ('ENT_HERX_NESTORIUS','opposes','ENT_SAINT_MARY','medium','Nestorius opposed the title Theotokos for Mary, rejecting it in favor of Christotokos, the dispute condemned at Ephesus.');
